using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ActorInspectorOperations
{
    public void add_shader_uniforms(Control owner,Resource actor,Resource data,Resource definition,VBoxContainer parent)
    {
        var source=_data.object_get_value(data,"shader_path","");if(source.VariantType==Variant.Type.Nil||source.VariantType==Variant.Type.String&&source.AsString().Length==0){add_label(parent,"Choose a .gdshader file to expose its uniforms.");return;}var shader=shader_from_value(source);if(shader==null){add_label(parent,"The selected shader could not be loaded.");return;}var property=_definitions.find_property(definition,"uniforms");if(property==null)return;var stored=_definitions.value_for(data,property).AsGodotDictionary();int shown=0;foreach(var entry in shader_uniform_layout(owner,shader,parent,actor.Get("id").AsString(),"ShaderUniforms:"+string.Join("/",_animation.path_to_object(actor,data)))){var info=entry["info"].AsGodotDictionary();string name=info.GetValueOrDefault("name","").AsString();if(name.Length==0)continue;var fallback=shader_uniform_default(shader,name,info.GetValueOrDefault("type",0).AsInt32());add_shader_uniform_value(owner,actor,data,definition,entry["parent"].As<VBoxContainer>(),name,stored.GetValueOrDefault(new StringName(name),fallback),fallback,info);shown++;}if(shown==0)add_label(parent,"This shader has no editable uniforms.");
    }
    public void add_shader_uniform_value(Control owner,Resource actor,Resource data,Resource definition,VBoxContainer parent,StringName name,Variant value,Variant fallback,Settings info)
    {
        int type=info.GetValueOrDefault("type",(int)fallback.VariantType).AsInt32();if(type==(int)Variant.Type.Object)fallback="";var defaultValue=fallback;var heading=new HBoxContainer();parent.AddChild(heading);string title=name.ToString().Capitalize();heading.AddChild(new Label{Text=title,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});var reset=new Button{Name=name+"_reset",Text="↺",Visible=!same_value(value,defaultValue)};heading.AddChild(reset);var property=new ActorProperty();property.Set("id",name);property.Set("label",title);property.Set("value_type",type);var options=new Settings{["default"]=defaultValue,["step"]=.01};property.Set("options",options);var path=_animation.path_to_object(actor,data);if(path.Length>0)add_keyframe_button(owner,heading,actor,property,path.Concat(new[]{"uniforms",name.ToString()}).ToArray(),defaultValue);if(info.GetValueOrDefault("hint",0).AsInt32()==(int)PropertyHint.Range){var parts=info.GetValueOrDefault("hint_string","").AsString().Split(',');if(parts.Length>=2){options["min"]=parts[0].ToFloat();options["max"]=parts[1].ToFloat();if(parts.Length>=3&&parts[2].IsValidFloat())options["step"]=parts[2].ToFloat();}}var uniformsProperty=_definitions.find_property(definition,"uniforms");if(uniformsProperty==null)return;Settings Current()=>animated_object_value(owner,actor,data,definition,uniformsProperty).AsGodotDictionary().Duplicate(true);var model=Ui<RefCounted>(owner,"model");void Change(Variant updated,string mode,Variant original)=>_timeline.edit_shader_uniform(model,actor,data,definition,name,updated,mode,original);void Commit(Variant updated){Change(updated,"edit",default);if(type==(int)Variant.Type.Object)owner.CallDeferred("_rebuild_selected");}var updaters=owner.Get("_updaters").AsGodotArray();updaters.Add(Callable.From(()=>reset.Visible=!same_value(Current().GetValueOrDefault(name,defaultValue),defaultValue)));reset.Pressed+=()=>{Commit(defaultValue);owner.CallDeferred("_rebuild_selected");};void Wire(SpinBox input,Func<double,Variant> make){var origin=Current();input.Connect("interaction_started",Callable.From(()=>origin=Current()));input.Connect("preview_changed",Callable.From<double>(n=>Change(make(n),"preview",default)));input.Connect("drag_committed",Callable.From<double>(n=>Change(make(n),"commit",origin)));input.Connect("drag_cancelled",Callable.From(()=>Change(origin.GetValueOrDefault(name,defaultValue),"preview",default)));input.ValueChanged+=n=>Commit(make(n));}
        switch((Variant.Type)type){case Variant.Type.Float:case Variant.Type.Int:var numeric=number_editor(owner,parent,value.AsDouble(),property);Wire(numeric,n=>type==(int)Variant.Type.Int?Variant.From((long)n):Variant.From(n));updaters.Add(Callable.From(()=>set_number_silent(numeric,Current().GetValueOrDefault(name,defaultValue).AsDouble())));break;
        case Variant.Type.Bool:var toggle=new CheckButton{Name=name+"_value",ButtonPressed=value.AsBool()};toggle.Toggled+=n=>Commit(n);parent.AddChild(toggle);updaters.Add(Callable.From(()=>toggle.SetPressedNoSignal(Current().GetValueOrDefault(name,defaultValue).AsBool())));break;
        case Variant.Type.Vector2:case Variant.Type.Vector3:case Variant.Type.Vector4:case Variant.Type.Vector2I:case Variant.Type.Vector3I:case Variant.Type.Vector4I:int count=_timeline.component_count(value);bool integer=(Variant.Type)type is Variant.Type.Vector2I or Variant.Type.Vector3I or Variant.Type.Vector4I;for(int i=0;i<count;i++){int axis=i;var row=new HBoxContainer();parent.AddChild(row);row.AddChild(new Label{Text=new[]{"X","Y","Z","W"}[axis]});var input=number(owner,ActorAnimationOperations.Component(value,axis).AsDouble(),.01);input.Name=name+"_"+axis;Wire(input,n=>ActorAnimationOperations.WithComponent(_data.copy_value(Current().GetValueOrDefault(name,value)),axis,integer?Variant.From((long)n):Variant.From(n)));updaters.Add(Callable.From(()=>input.SetValueNoSignal(ActorAnimationOperations.Component(Current().GetValueOrDefault(name,defaultValue),axis).AsDouble())));row.AddChild(input);}break;
        case Variant.Type.Color:var color=new LiveColorPickerButton();color.Name=name+"_value";color.Color=value.AsColor();color.Connect("preview_changed",Callable.From<Color>(updated=>Change(updated,"preview",default)));color.Connect("drag_committed",Callable.From<Color,Color>((_,updated)=>Commit(updated)));parent.AddChild(color);updaters.Add(Callable.From(()=>color.Call("set_color_silent",Current().GetValueOrDefault(name,defaultValue))));break;
        case Variant.Type.Object:owner.Call("_add_uniform_texture_slot",actor,data,definition,parent,name,title);break;
        default:var text=new LineEdit{Name=name+"_value",Text=GD.VarToStr(value),TooltipText="Edit this value using Godot Variant syntax, then press Enter."};text.TextSubmitted+=input=>{var parsed=GD.StrToVar(input);if((int)parsed.VariantType==type)Commit(parsed);};parent.AddChild(text);updaters.Add(Callable.From(()=>text.Text=GD.VarToStr(Current().GetValueOrDefault(name,defaultValue))));break;}
    }
}
